/// Read grid coordinates for a structured zone.
///
/// `name` is the coordinate name (e.g. "CoordinateX") and `rmin` / `rmax`
/// specify the (1-based) index range to read.  Returns the data in a `Vec<f64>`.
pub fn coord_read(
    fn_: i32,
    base: i32,
    zone: i32,
    data_type: u32,
    name: &str,
    rmin: &[i64],
    rmax: &[i64],
    data: &mut [f64],
) -> Result<(), String> {
    let _guard = lock_cgns();
    let c_name = std::ffi::CString::new(name)
        .map_err(|e| format!("invalid coordinate name: {}", e))?;
    let status = unsafe {
        cg_coord_read(
            fn_,
            base,
            zone,
            c_name.as_ptr(),
            data_type,
            rmin.as_ptr(),
            rmax.as_ptr(),
            data.as_mut_ptr() as *mut std::ffi::c_void,
        )
    };
    status_to_result(status)
}

/// Read a flow solution field.
pub fn field_read(
    fn_: i32,
    base: i32,
    zone: i32,
    sol: i32,
    data_type: u32,
    name: &str,
    rmin: &[i64],
    rmax: &[i64],
    data: &mut [f64],
) -> Result<(), String> {
    let _guard = lock_cgns();
    let c_name = std::ffi::CString::new(name)
        .map_err(|e| format!("invalid field name: {}", e))?;
    let status = unsafe {
        cg_field_read(
            fn_,
            base,
            zone,
            sol,
            c_name.as_ptr(),
            data_type,
            rmin.as_ptr(),
            rmax.as_ptr(),
            data.as_mut_ptr() as *mut std::ffi::c_void,
        )
    };
    status_to_result(status)
}
